def transform(grid):
    from collections import Counter
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    outer = g[0][0]
    counts = Counter(v for row in g for v in row if v != outer)
    frame = counts.most_common(1)[0][0]
    seen = set()
    boxes = []
    for r in range(h):
        for c in range(w):
            if g[r][c] != frame or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            pts = []
            while stack:
                y, x = stack.pop()
                pts.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y+dy, x+dx
                    if 0 <= ny < h and 0 <= nx < w and g[ny][nx] == frame and (ny,nx) not in seen:
                        seen.add((ny,nx))
                        stack.append((ny,nx))
            boxes.append((min(y for y,x in pts), max(y for y,x in pts),
                          min(x for y,x in pts), max(x for y,x in pts)))
    for top, bottom, left, right in boxes:
        a, b = top+1, bottom
        c, d = left+1, right
        if b <= a or d <= c:
            continue
        vertical = b-a >= d-c
        n = b-a if vertical else d-c
        m = d-c if vertical else b-a
        best = None
        for p in range(1, n//2+1):
            expected = {}
            mismatch = 0
            for phase in range(p):
                for j in range(m):
                    vals = [g[a+i][c+j] if vertical else g[a+j][c+i]
                            for i in range(phase, n, p)]
                    common = Counter(vals).most_common(1)[0][0]
                    expected[phase,j] = common
                    mismatch += sum(v != common for v in vals)
            key = (mismatch, p)
            if best is None or key < best[0]:
                best = (key, expected)
        p = best[0][1]
        expected = best[1]
        for i in range(n):
            for j in range(m):
                if vertical:
                    g[a+i][c+j] = expected[i%p,j]
                else:
                    g[a+j][c+i] = expected[i%p,j]
    return g
